SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

-- Live demo (https://demomlm.omc.co.th/) — user confirmed 2026-11-04: visitors try it directly, no request needed.
-- Home hero primary button and the /demo/ hero point at the demo (opens in a new tab · site-button.php);
-- /demo/ keeps its lead form as "book a guided demo" (#lead-form).
-- Each UPDATE only touches a page whose first block is still the hero (content edited in the CMS keeps its shape).

-- /  ·  home hero primary button → live demo
UPDATE pages SET blocks = JSON_SET(blocks, '$[0].data.actions[0]', JSON_OBJECT('label', CONVERT(X'E0B897E0B894E0B8A5E0B8ADE0B887E0B983E0B88AE0B9892044656D6F' USING utf8mb4), 'url', 'https://demomlm.omc.co.th/', 'style', 'primary')), updated_at = NOW()
WHERE path = CONVERT(X'2F' USING utf8mb4) COLLATE utf8mb4_bin AND locale = 'th' AND deleted_at IS NULL AND JSON_UNQUOTE(JSON_EXTRACT(blocks, '$[0].type')) = 'hero';

-- /demo/  ·  ทดลองใช้ Demo ระบบ MLM
UPDATE pages SET title = CONVERT(X'E0B897E0B894E0B8A5E0B8ADE0B887E0B983E0B88AE0B9892044656D6F20E0B8A3E0B8B0E0B89AE0B89A204D4C4D' USING utf8mb4), seo_title = CONVERT(X'E0B897E0B894E0B8A5E0B8ADE0B887E0B983E0B88AE0B9892044656D6F20E0B982E0B89BE0B8A3E0B981E0B881E0B8A3E0B8A1E0B882E0B8B2E0B8A2E0B895E0B8A3E0B887204D4C4D20536F66747761726520E0B89FE0B8A3E0B8B5207C204F4D43' USING utf8mb4), meta_description = CONVERT(X'' USING utf8mb4),
  blocks = JSON_SET(blocks,
    '$[0].data.title', CONVERT(X'E0B897E0B894E0B8A5E0B8ADE0B887E0B983E0B88AE0B9892044656D6F20E0B8A3E0B8B0E0B89AE0B89AE0B882E0B8B2E0B8A2E0B895E0B8A3E0B887' USING utf8mb4),
    '$[0].data.lead', CONVERT(X'' USING utf8mb4),
    '$[0].data.bullets', JSON_ARRAY(CONVERT(X'' USING utf8mb4), CONVERT(X'' USING utf8mb4), CONVERT(X'' USING utf8mb4)),
    '$[0].data.actions', JSON_ARRAY(
      JSON_OBJECT('label', CONVERT(X'E0B980E0B89BE0B8B4E0B894E0B8A3E0B8B0E0B89AE0B89A2044656D6F' USING utf8mb4), 'url', 'https://demomlm.omc.co.th/', 'style', 'primary'),
      JSON_OBJECT('label', CONVERT(X'E0B899E0B8B1E0B894E0B897E0B8B5E0B8A1E0B887E0B8B2E0B899E0B89EE0B8B2E0B894E0B8B9' USING utf8mb4), 'url', '#lead-form', 'style', 'secondary'))),
  updated_at = NOW()
WHERE path = CONVERT(X'2F64656D6F2F' USING utf8mb4) COLLATE utf8mb4_bin AND locale = 'th' AND deleted_at IS NULL AND JSON_UNQUOTE(JSON_EXTRACT(blocks, '$[0].type')) = 'hero';

-- /en/  ·  home hero primary button → live demo
