  blocks = JSON_SET(blocks,
    '$[0].data.title', CONVERT(X'54727920746865206469726563742073656C6C696E672073797374656D2064656D6F' USING utf8mb4),
    '$[0].data.lead', CONVERT(X'' USING utf8mb4),
    '$[0].data.bullets', JSON_ARRAY(CONVERT(X'537461727420696D6D6564696174656C793A207468652064656D6F206163636F756E742069732066696C6C656420696E2C20796F75206F6E6C792074797065207468652063617074636861' USING utf8mb4), CONVERT(X'53656520746865207265616C206D656D626572206261636B206F66666963653A2067656E65616C6F67792C20706F696E747320616E6420626F6E7573207265706F727473' USING utf8mb4), CONVERT(X'57616E7420746F207365652074686520636F6D70616E79206261636B206F6666696365206F72206469736375737320637573746F6D69736174696F6E3F20426F6F6B20746865207465616D20666F722066726565' USING utf8mb4)),
    '$[0].data.actions', JSON_ARRAY(
      JSON_OBJECT('label', CONVERT(X'4F70656E207468652064656D6F' USING utf8mb4), 'url', 'https://demomlm.omc.co.th/', 'style', 'primary'),
