WHERE path = CONVERT(X'2F656E2F64656D6F2F' USING utf8mb4) COLLATE utf8mb4_bin AND locale = 'en' AND deleted_at IS NULL AND JSON_UNQUOTE(JSON_EXTRACT(blocks, '$[0].type')) = 'hero';

